(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.015+t*0.32)*11 + Math.cos((x-y)*0.01-t*0.18)*7;
  const w2x = Math.sin(w1x*0.025+t*0.4)*6 + Math.cos(w1y*0.02-t*0.35)*5;
  const w2y = Math.cos(w1y*0.022+t*0.38)*5 + Math.sin(w1x*0.018-t*0.42)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.6)*110, 60+Math.cos(t*0.4)*50, 0.07, 2.2],
    [360+Math.cos(t*0.5)*100, 60+Math.sin(t*0.7)*45, 0.09, 1.8],
    [160+Math.sin(t*0.3+2)*130, 170+Math.cos(t*0.5+1)*80, 0.055, 2.5],
    [320+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*70, 0.11, 1.6],
    [400+Math.sin(t*0.4+4)*80, 120+Math.cos(t*0.9+2)*60, 0.065, 2.8],
    [80+Math.cos(t*0.35+5)*100, 140+Math.sin(t*0.55)*90, 0.08, 2.0],
    [240+Math.sin(t*0.45+3)*60, 30+Math.cos(t*0.65+4)*25, 0.13, 1.4],
    [240+Math.cos(t*0.38+1)*70, 210+Math.sin(t*0.58+2)*30, 0.12, 1.5],
    [60+Math.sin(t*0.7+6)*50, 210+Math.cos(t*0.5+5)*40, 0.085, 2.1],
    [420+Math.cos(t*0.42+3)*55, 200+Math.sin(t*0.72+1)*35, 0.075, 2.4]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7);
    aS2 += Math.cos(d*f*1.4-t*sp*0.8+0.5)*0.5;
    iS2 += Math.sin(d*f*0.9+t*sp*0.7+3.1)*0.4;
  }
  const act=(aS+aS2)/10, inh=(iS+iS2)/10;
  const bg=(Math.sin(sx*0.035+sy*0.02+t*0.9)+Math.sin(sx*0.025-sy*0.035+t*1.2)+Math.sin(sx*0.05+sy*0.04-t*0.7))/3;
  const micro=(Math.sin(sx*0.12+sy*0.08+t*1.8)*Math.sin(sx*0.09-sy*0.11-t*1.5)+Math.sin((sx-sy)*0.15+t*2.8)*0.3)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.035+ang*4.5-t*1.3)+Math.sin(dist*0.06-ang*2-t*2.1))*0.3;
  const pulse=Math.sin(dist*0.03-t*1.2)*Math.cos(ang*2+t*0.5)*0.3;
  const rd1=Math.tanh((act-inh*0.65+bg*0.35+spiral)*2.0);
  const rd2=Math.tanh((act*0.8+inh*0.5-bg*0.4-spiral*0.6+pulse)*1.8);
  const feedback=Math.tanh((rd1*0.6-rd2*0.4+micro)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.6+Math.sin(sx*0.07-t*0.5)*Math.cos(sy*0.08+t*0.3))*1.4)*0.2;
  const voronoi=((Math.min(Math.abs(Math.sin(sx*0.08+t*0.3)),Math.abs(Math.sin(sy*0.08-t*0.25)))-0.3)*3);
  const blend=feedback*0.5+rd1*0.2+rd2*0.1+cell*0.12+Math.max(0,voronoi)*0.08;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[12,35,85],[18,70,120],[25,120,135],
    [60,170,140],[140,195,100],[210,190,70],[220,150,60],
    [200,100,75],[160,55,80],[100,30,75],[50,15,55],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.75+Math.sin(feedback*Math.PI)*0.25;
  const edge=Math.abs(feedback)>0.65?1.2:Math.abs(rd1)>0.5?1.1:1.0;
  const glow=Math.max(0,feedback)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*50)|0)
  ];
}
